draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // brain
  ctx.fillStyle = 'white';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 100, 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();

  // thought bubble
  ctx.beginPath();
  ctx.arc(W/2 + 150 + 50 * Math.sin(t), H/2 - 50 + 20 * Math.cos(t), 50, 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();

  // stick figure
  ctx.beginPath();
  ctx.arc(W/2, H/2 + 150, 20, 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 170);
  ctx.lineTo(W/2, H/2 + 250);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 200);
  ctx.lineTo(W/2 - 50, H/2 + 230);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 200);
  ctx.lineTo(W/2 + 50, H/2 + 230);
  ctx.stroke();

  // psychology symbol
  ctx.font = '30px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = 'black';
  ctx.fillText('Ψ', W/2, H/2 + 300 + 20 * Math.sin(t));

  ctx.restore();
}
